import React from "react";
import {
  FaClone,
  FaUserCog,
  FaUserEdit,
  FaPhoneAlt,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaMicrochip,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaSyncAlt,
  FaFileAlt,
  FaCoins,
  FaBoxOpen,
  FaFileInvoice,
  FaExclamationCircle,
  FaChevronLeft,
  FaCommentDots,
} from "react-icons/fa";

import InfoField from "./InfoFieldComponenet";
import withRouter from "./withRouter";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";
const FILE_URL = "https://iranaserviceapp.ir/test/files/clear/";

class RequestDetailPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: null,
      clear: null,
      loading: true,
      authenticated: false,
    };

    this.handleBack = this.handleBack.bind(this);
    this.handleChat = this.handleChat.bind(this);
    this.handleAddRelated = this.handleAddRelated.bind(this);
    this.getRequestDetail = this.getRequestDetail.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getRequestDetail();
      }
    );
  }

  getRequestDetail() {
    const { id } = this.props.params;
    const token = localStorage.getItem("token");

    if (!id) {
      console.error("REQUEST ID NOT FOUND");

      this.setState({
        loading: false,
      });

      return;
    }

    fetch(`${API_URL}/detail?id=${id}`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error(`HTTP Error: ${response.status}`);
        }

        return response.json();
      })
      .then((data) => {
        console.log("REQUEST DETAIL:", data);

        if (String(data.status) !== "1") {
          this.setState({
            request: null,
            clear: null,
            loading: false,
          });

          return;
        }

        this.setState({
          request: data.request || null,
          clear: data.clear || null,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET REQUEST DETAIL ERROR:", error);

        this.setState({
          request: null,
          clear: null,
          loading: false,
        });
      });
  }

  handleBack() {
    this.props.navigate(-1);
  }

  handleChat() {
    console.log("رفتن به گفتگو");
  }

  handleAddRelated() {
    console.log("افزودن درخواست مرتبط");
  }

  formatNumber(value) {
    if (
      value === null ||
      value === undefined ||
      value === ""
    ) {
      return "—";
    }

    const number = Number(value);

    if (Number.isNaN(number)) {
      return value;
    }

    return number.toLocaleString("fa-IR");
  }

  getTechnicianName(request) {
    if (!request) {
      return "—";
    }

    const technician = request.repairman_model;

    if (!technician) {
      return "—";
    }

    const name = technician.name || "";
    const family = technician.family || "";

    const fullName = `${name} ${family}`.trim();

    return fullName || "—";
  }

  getProvince(request) {
    if (
      request &&
      request.state_model &&
      request.state_model.name
    ) {
      return request.state_model.name;
    }

    return "—";
  }

  getReceiptImage(clear, request) {
    /*
     * اولویت با clear است
     */

    const file =
      clear?.file1 ||
      request?.file1 ||
      null;

    if (!file) {
      return null;
    }

    return `${FILE_URL}${file}`;
  }

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      request,
      clear,
      loading,
    } = this.state;

    if (loading) {
      return (
        <div className="text-center text-muted py-5">
          در حال دریافت اطلاعات درخواست...
        </div>
      );
    }

    if (!request) {
      return (
        <div className="text-center text-muted py-5">
          درخواست مورد نظر پیدا نشد.
        </div>
      );
    }

    /*
     * ==========================
     * اطلاعات درخواست
     * ==========================
     */

    const requestNumber =
      request.code ||
      request.id ||
      "—";

    const technicianName =
      this.getTechnicianName(request);

    const customerName =
      request.customer_name ||
      request.customer ||
      request.customerName ||
      "—";

    const phone =
      request.mobile ||
      request.phone ||
      request.customer_mobile ||
      "—";

    const landline =
      request.tel ||
      request.landline ||
      request.phone2 ||
      "—";

    const province =
      this.getProvince(request);

    const address =
      request.address ||
      request.customer_address ||
      "—";

    const deviceType =
      request.device ||
      request.device_type ||
      request.type ||
      "—";

    const deviceBrand =
      request.brand ||
      request.brand_name ||
      "—";

    const deviceIssue =
      request.problem ||
      request.issue ||
      request.description ||
      "—";

    const visitTime =
      request.time ||
      request.visit_time ||
      "—";

    /*
     * ==========================
     * اطلاعات مالی درخواست
     * ==========================
     */

    const requestTotalReceived =
      request.price ||
      request.total ||
      request.total_received ||
      null;

    const requestSuppliesCost =
      request.supplies_cost ||
      request.tools ||
      request.lavazem ||
      null;

    const requestSuppliesUsed =
      request.supplies_used ||
      request.supplies ||
      request.lavazem_text ||
      null;

    const requestTotalFee =
      request.total_fee ||
      request.fee ||
      null;

    const requestCommissionPercent =
      request.commission_percent ||
      request.percent ||
      null;

    const requestCommissionAmount =
      request.commission ||
      request.commission_amount ||
      null;

    /*
     * ==========================
     * اطلاعات CLEAR
     * ==========================
     *
     * اگر clear وجود داشته باشد،
     * اطلاعات تسویه از این قسمت خوانده می‌شود.
     */

    const clearExists =
      clear !== null &&
      clear !== undefined;

    const clearSum =
      clearExists
        ? clear.sum
        : null;

    const clearDescription =
      clearExists
        ? (
            clear.description ||
            clear.desc ||
            clear.text2 ||
            clear.text3 ||
            null
          )
        : null;

    const clearCode =
      clearExists
        ? (
            clear.text1 ||
            null
          )
        : null;

    const clearCommission =
      clearExists
        ? (
            clear.commission ||
            clear.commission_amount ||
            null
          )
        : null;

    const clearCommissionPercent =
      clearExists
        ? (
            clear.commission_percent ||
            clear.percent ||
            null
          )
        : null;

    const clearSuppliesCost =
      clearExists
        ? (
            clear.supplies_cost ||
            clear.lavazem ||
            clear.tools ||
            null
          )
        : null;

    const clearSuppliesUsed =
      clearExists
        ? (
            clear.supplies_used ||
            clear.supplies ||
            clear.lavazem_text ||
            null
          )
        : null;

    const clearTotalFee =
      clearExists
        ? (
            clear.total_fee ||
            clear.fee ||
            clear.ojrat ||
            null
          )
        : null;

    /*
     * ==========================
     * انتخاب مقدار نهایی
     * ==========================
     */

    const totalReceived =
      clearExists && clearSum !== null
        ? clearSum
        : requestTotalReceived;

    const suppliesCost =
      clearExists && clearSuppliesCost !== null
        ? clearSuppliesCost
        : requestSuppliesCost;

    const suppliesUsed =
      clearExists && clearSuppliesUsed !== null
        ? clearSuppliesUsed
        : requestSuppliesUsed;

    const totalFee =
      clearExists && clearTotalFee !== null
        ? clearTotalFee
        : requestTotalFee;

    const commissionPercent =
      clearExists && clearCommissionPercent !== null
        ? clearCommissionPercent
        : requestCommissionPercent;

    const commissionAmount =
      clearExists && clearCommission !== null
        ? clearCommission
        : requestCommissionAmount;

    /*
     * اگر clear وجود داشته باشد،
     * توضیحات تسویه نمایش داده می‌شود.
     */

    const settlementDescription =
      clearDescription || null;

    /*
     * فیش
     */

    const receiptImage =
      this.getReceiptImage(
        clear,
        request
      );

    /*
     * درخواست‌های مرتبط
     */

    let relatedRequests = [];

    if (
      Array.isArray(request.siblings)
    ) {
      relatedRequests =
        request.siblings;
    }

    /*
     * ==========================
     * RENDER
     * ==========================
     */

    return (
      <div dir="rtl">
        <div className="container px-3 pt-4 pb-5">

          {/* هدر */}
          <div className="d-flex align-items-center justify-content-between mb-4">

            <button
              type="button"
              onClick={this.handleBack}
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaChevronLeft size={14} />
            </button>

            <button
              type="button"
              onClick={this.handleChat}
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center text-danger"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaCommentDots size={16} />
            </button>

          </div>

          {/* شماره درخواست */}
          <InfoField
            icon={<FaClone size={18} />}
            label="شماره درخواست"
            value={requestNumber}
          />

          {/* کد تسویه - فقط اگر clear وجود داشته باشد */}
          {clearExists && clearCode && (
            <InfoField
              icon={<FaFileAlt size={18} />}
              label="کد تسویه"
              value={clearCode}
            />
          )}

          {/* نام تعمیرکار */}
          <InfoField
            icon={<FaUserCog size={18} />}
            label="نام تعمیرکار"
            value={technicianName}
          />

          {/* نام مشتری */}
          <InfoField
            icon={<FaUserEdit size={18} />}
            label="نام مشتری"
            value={customerName}
          />

          {/* شماره تماس */}
          <InfoField
            icon={<FaPhoneAlt size={18} />}
            label="شماره تماس"
            value={phone}
          />

          {/* تلفن ثابت */}
          <InfoField
            icon={<FaPhone size={18} />}
            label="تلفن ثابت"
            value={landline}
          />

          {/* استان */}
          <InfoField
            icon={<FaMapMarkerAlt size={18} />}
            label="استان"
            value={province}
          />

          {/* آدرس */}
          <InfoField
            icon={<FaImage size={18} />}
            label="آدرس"
            value={address}
          />

          {/* نوع دستگاه */}
          <InfoField
            icon={<FaMicrochip size={18} />}
            label="نوع دستگاه"
            value={deviceType}
          />

          {/* برند دستگاه */}
          <InfoField
            icon={<FaTag size={18} />}
            label="برند دستگاه"
            value={deviceBrand}
          />

          {/* ایراد دستگاه */}
          <InfoField
            icon={<FaQuestionCircle size={18} />}
            label="ایراد دستگاه"
            value={deviceIssue}
          />

          {/* زمان مراجعه */}
          <InfoField
            icon={<FaClock size={18} />}
            label="زمان مراجعه"
            value={visitTime}
          />

          {/* توضیحات */}
          <InfoField
            icon={<FaSyncAlt size={18} />}
            label="توضیحات"
            value={
              request.description ||
              request.desc ||
              "—"
            }
          />

          {/* وضعیت */}
          <InfoField
            icon={<FaFileAlt size={18} />}
            label="وضعیت"
          >
            <span className="text-primary fw-semibold">
              {request.status || "—"}
            </span>
          </InfoField>

          {/* ========================= */}
          {/* اطلاعات مالی */}
          {/* ========================= */}

          <InfoField
            icon={<FaCoins size={18} />}
            label="کل دریافتی"
          >
            <span className="fw-semibold">
              {totalReceived !== null
                ? `${this.formatNumber(totalReceived)} تومان`
                : "—"}
            </span>
          </InfoField>

          <InfoField
            icon={<FaCoins size={18} />}
            label="هزینه لوازم مصرفی"
          >
            <span className="fw-semibold">
              {suppliesCost !== null
                ? `${this.formatNumber(suppliesCost)} تومان`
                : "—"}
            </span>
          </InfoField>

          <InfoField
            icon={<FaBoxOpen size={18} />}
            label="لوازم مصرفی"
            value={
              suppliesUsed || "—"
            }
          />

          <InfoField
            icon={<FaFileInvoice size={18} />}
            label="کل اجرت"
          >
            <span className="fw-semibold">
              {totalFee !== null
                ? `${this.formatNumber(totalFee)} تومان`
                : "—"}
            </span>
          </InfoField>

          <InfoField
            icon={<FaFileInvoice size={18} />}
            label={
              commissionPercent !== null
                ? `پورسانت (%${commissionPercent})`
                : "پورسانت"
            }
          >
            <span className="fw-semibold">
              {commissionAmount !== null
                ? `${this.formatNumber(
                    commissionAmount
                  )} تومان`
                : "—"}
            </span>
          </InfoField>

          {/* ========================= */}
          {/* فیش واریزی */}
          {/* ========================= */}

          {receiptImage && (
            <div className="d-flex align-items-center justify-content-between gap-3 border rounded-4 px-3 py-3 mb-3 bg-white">

              <span className="text-muted">
                فیش واریزی:
              </span>

              <img
                src={receiptImage}
                alt="فیش واریزی"
                className="rounded-3 border"
                style={{
                  width: 140,
                  height: 110,
                  objectFit: "cover",
                  cursor: "pointer",
                }}
                onClick={() => {
                  window.open(
                    receiptImage,
                    "_blank",
                    "noopener,noreferrer"
                  );
                }}
              />

            </div>
          )}

          {/* ========================= */}
          {/* توضیحات تایید تسویه */}
          {/* ========================= */}

          {clearExists && (
            <InfoField
              icon={
                <FaExclamationCircle
                  size={18}
                />
              }
              label="توضیحات تایید تسویه"
              value={
                settlementDescription ||
                "—"
              }
            />
          )}

          {/* ========================= */}
          {/* درخواست‌های مرتبط */}
          {/* ========================= */}

          <h2 className="fs-6 fw-semibold text-dark mt-4 mb-3 text-end">
            درخواست‌های مرتبط:
          </h2>

          {relatedRequests.length === 0 ? (
            <div className="text-center text-muted py-4">
              هنوز موردی برای نمایش وجود ندارد.
            </div>
          ) : (
            <div>

              {relatedRequests.map(
                (rel) => (
                  <div
                    key={rel.id}
                    className="border rounded-3 p-3 mb-2 text-end bg-white"
                  >

                    <div className="fw-semibold">
                      {rel.code ||
                        rel.text1 ||
                        `درخواست ${rel.id}`}
                    </div>

                    {rel.description && (
                      <div className="small text-muted mt-1">
                        {rel.description}
                      </div>
                    )}

                  </div>
                )
              )}

            </div>
          )}

          {/* افزودن درخواست مرتبط */}
          <button
            type="button"
            onClick={
              this.handleAddRelated
            }
            className="btn btn-primary w-100 rounded-3 py-3 mt-2"
            style={{
              transition:
                "opacity 0.15s ease",
            }}
          >
            افزودن درخواست مرتبط
          </button>

        </div>
      </div>
    );
  }
}

export default withRouter(
  RequestDetailPage
);
